import xfacthd.framedblocks.common.menu.FramingSawMenu;
import xfacthd.framedblocks.common.net.SelectFramingSawRecipePacket;

public final class FramingSawTransferHandler
implements IRecipeTransferHandler<FramingSawMenu, FramingSawRecipe> {
    private final IRecipeTransferHandlerHelper transferHelper;
    private final IRecipeTransferInfo<FramingSawMenu, FramingSawRecipe> transferInfo;
    private final IRecipeTransferHandler<FramingSawMenu, FramingSawRecipe> wrappedHandler;

    public FramingSawTransferHandler(IRecipeTransferHandlerHelper transferHelper) {
        this.transferHelper = transferHelper;
        this.transferInfo = transferHelper.createBasicRecipeTransferInfo(FramingSawMenu.class, (MenuType)FBContent.MENU_TYPE_FRAMING_SAW.get(), FramedJeiPlugin.FRAMING_SAW_RECIPE_TYPE, 0, 4, 5, 36);
        this.wrappedHandler = transferHelper.createUnregisteredRecipeTransferHandler(this.transferInfo);
    }

    public Class<? extends FramingSawMenu> getContainerClass() {
        return this.transferInfo.getContainerClass();
    }

    public Optional<MenuType<FramingSawMenu>> getMenuType() {
        return this.transferInfo.getMenuType();
    }

    public RecipeType<FramingSawRecipe> getRecipeType() {
        return this.transferInfo.getRecipeType();
    }

    @Nullable
    public IRecipeTransferError transferRecipe(FramingSawMenu menu, FramingSawRecipe recipe, IRecipeSlotsView recipeSlots, Player player, boolean maxTransfer, boolean doTransfer) {
        int idx = FramingSawRecipeCache.get(true).getRecipes().indexOf(recipe);
        if (idx != -1 && menu.isValidRecipeIndex(idx)) {
            if (doTransfer && menu.m_6366_(player, idx)) {
                FramedBlocks.CHANNEL.send(PacketDistributor.SERVER.noArg(), (Object)new SelectFramingSawRecipePacket(menu.f_38840_, idx));
            }
            return new RecipeTransferErrorTransferNotImplemented();
        }
        return this.transferHelper.createUserErrorWithTooltip(JeiCompat.MSG_INVALID_RECIPE);
    }
}

