@REIPluginClient
public final class FramedReiPlugin
implements REIClientPlugin {
    public void registerCategories(CategoryRegistry registry) {
        registry.add((DisplayCategory)new FramingSawRecipeCategory());
        registry.addWorkstations(FramingSawRecipeCategory.SAW_CATEGORY, new EntryStack[]{EntryStacks.of((ItemLike)((ItemLike)FBContent.BLOCK_FRAMING_SAW.get())), EntryStacks.of((ItemLike)((ItemLike)FBContent.BLOCK_POWERED_FRAMING_SAW.get()))});
    }

    public void registerDisplays(DisplayRegistry registry) {
