        }
        widgets.add(Widgets.createResultSlotBackground((Point)new Point(topLeft.x + 99, topLeft.y + 16)));
        widgets.add((Widget)Widgets.createSlot((Point)new Point(topLeft.x + 99, topLeft.y + 16)).entries((Collection)display.getOutputEntries().get(0)).disableBackground().markOutput());
